SELECT Name, Quota, Sales

      FROM Salesperson

      WHERE emp_no = 107;

SELECT City, Mgr

      FROM Offices 

      WHERE Mgr <> 108;

SELECT loan_number 

      FROM loan

      WHERE branch_name = Perryridge AND amount > 1200;

SELECT loan_number 

     FROM loan

     WHERE amount BETWEEN 2000 AND 100000;

SELECT order_no, date, product, amount

     FROM orders

     WHERE date BETWEEN '01-OCT-06' AND '31-DEC-06';

SELECT customer_name 

     FROM customer

     WHERE customer_street LIKE '%Main%';

SELECT AVG(balance)

     FROM account

     WHERE branch_name = 'Perryridge';

SELECT branch_name, AVG(balance)

     FROM account

     GROUP BY branch_name;
